INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (1,'Martin Luther','theologian','16th','Theologian & Reformer','1483-1546','Martin Luther was a German priest, theologian, author, hymnwriter, professor, and former Augustinian friar. Luther was the seminal figure of the Protestant Reformation, and his theological beliefs form the basis of Lutheranism. He is considered one of the most influential figures in Western and Christian history.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/1.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (2,'John Calvin','theologian','16th','Theologian & Reformer','1509-1564','John Calvin was a French theologian, pastor and reformer in Geneva during the Protestant Reformation. He was the principal figure in the development of the system of Christian theology later called Calvinism, including its doctrines of predestination and of God''s absolute sovereignty in the salvation of the human soul from death and eternal damnation. Calvinist doctrines were influenced by and elaborated upon Augustinian and other Christian traditions. Various Reformed Church movements, including Continental Reformed, Congregationalism, Presbyterianism, Waldensians, Baptist Reformed, Calvinist Methodism, and Reformed Anglican Churches, which look to Calvin as the chief expositor of their beliefs, have spread throughout the world.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/2.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (3,'Dietrich Bonhoeffer','theologian','20th','Theologian & Martyr','1906-1945','Dietrich Bonhoeffer was a German Lutheran pastor, neo-orthodox theologian and anti-Nazi dissident who was a key founding member of the Confessing Church. His writings on Christianity''s role in the secular world have become widely influential; his 1937 book The Cost of Discipleship is described as a modern classic. Apart from his theological writings, Bonhoeffer was known for his staunch resistance to the Nazi dictatorship, including vocal opposition to Nazi euthanasia program and genocidal persecution of Jews. He was arrested in April 1943 by the Gestapo and imprisoned at Tegel Prison for a year and a half. Later, he was transferred to Flossenbürg concentration camp.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/3.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (4,'Charles Spurgeon','theologian','19th','Preacher & Pastor','1834-1892','Charles Haddon Spurgeon was an English Particular Baptist preacher. Spurgeon remains highly influential among Christians of various denominations, to some of whom he is known as the "Prince of Preachers." He was a strong figure in the Baptist tradition, defending the 1689 London Baptist Confession of Faith, and opposing the liberal and pragmatic theological tendencies in the Church of his day.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/4.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (5,'John Wesley','theologian','18th','Theologian & Evangelist','1703-1791','John Wesley was an English cleric, theologian, and evangelist who was a principal leader of a revival movement within the Church of England known as Methodism. The societies he founded became the dominant form of the independent Methodist movement that continues to this day.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/5.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (6,'John Wycliffe','theologian','14th','Theologian & Bible Translator','1320-1384','John Wycliffe was an English scholastic philosopher, Christian reformer, Catholic priest, and a theology professor at the University of Oxford. Wycliffe is traditionally believed to have advocated for or made a vernacular translation of the Vulgate Bible into Middle English, though more recent scholarship has minimised the extent of his advocacy or involvement for lack of direct contemporary evidence.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/6.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (7,'William Tyndale','theologian','16th','Bible Translator & Martyr','1494-1536','William Tyndale was an English Biblical scholar and linguist who became a leading figure in the Protestant Reformation in the years leading up to his execution. He translated much of the Bible into English and was influenced by the works of prominent Protestant Reformers such as Martin Luther.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/7.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (8,'Jonathan Edwards','theologian','18th','Theologian & Revivalist','1703-1758','Jonathan Edwards was an American revivalist preacher, philosopher, and Congregationalist theologian. Edwards is widely regarded as one of America''s most important and original philosophical theologians. Edwards''s theological work is broad in scope but rooted in the Puritan heritage as exemplified in the Westminster and Savoy Confessions of Faith. Recent studies have emphasized how thoroughly Edwards grounded his life''s work on conceptions of beauty, harmony, and ethical aptness, and how central the Age of Enlightenment was to his mindset. Edwards played a critical role in shaping the First Great Awakening and oversaw some of the first revivals in 1733–35 at his church in Northampton, Massachusetts. His work gave rise to a doctrine known as New England theology.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/8.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (9,'George Whitefield','theologian','18th','Evangelist & Preacher','1714-1770','George Whitefield, was an English Anglican priest and preacher who was one of the founders of Methodism and the evangelical movement.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/9.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (10,'John Knox','theologian','16th','Reformer & Preacher','1514-1572','John Knox was a Scottish minister, Reformed theologian, and writer who was a leader of the country''s Reformation. He was the reformer of the Church of Scotland.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/10.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (11,'Ulrich Zwingli','theologian','16th','Reformer & Pastor','1484-1531','Huldrych Zwingli was a Swiss Christian theologian, musician, and leader of the Reformation in Switzerland. Born during a time of emerging Swiss patriotism and increasing criticism of the Swiss mercenary system, he attended the University of Vienna and the University of Basel, a scholarly center of Renaissance humanism. He continued his studies while he served as a pastor in Glarus and later in Einsiedeln, where he was influenced by the writings of Erasmus. During his tenures at Basel and Einsiedeln, Zwingli began to familiarize himself with many criticisms Christian institutions were facing regarding their reform guidance and garnered scripture which aimed to address such criticisms.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/11.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (12,'Philip Melanchthon','theologian','16th','Theologian & Scholar','1497-1560','Philip Melanchthon was a German Lutheran reformer, collaborator with Martin Luther, the first systematic theologian of the Protestant Reformation, an intellectual leader of the Lutheran Reformation, and influential designer of educational systems. Along with Luther and John Calvin, he played a major role in shaping Protestantism.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/12.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (13,'Karl Barth','theologian','20th','Theologian & Author','1886-1968','Karl Barth was a Swiss Reformed theologian. Barth is best known for his commentary The Epistle to the Romans, his involvement in the Confessing Church, including his authorship of the Barmen Declaration, and especially his unfinished multi-volume theological summa the Church Dogmatics. Barth''s influence expanded well beyond the academic realm to mainstream culture, leading him to be featured on the cover of Time on 20 April 1962.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/13.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (14,'John Owen','theologian','17th','Puritan Theologian','1616-1683','John Owen was an English Puritan Nonconformist church leader, theologian, and vice-chancellor of the University of Oxford. One of the most prominent theologians in England during his lifetime, Owen was a prolific author who wrote articles, treatises, Biblical commentaries, poetry, children''s catechisms, and other works. Many of Owen''s works reflect the Reformed tradition of Christianity. Owen is still widely read by Reformed Christians today, and is known particularly for his writings on sin and human depravity.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/14.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (15,'Richard Baxter','theologian','17th','Puritan Pastor & Author','1615-1691','Richard Baxter was an English Nonconformist church leader and theologian from Rowton, Shropshire, who has been described as "the chief of English Protestant Schoolmen". He made his reputation in the late 1630s by his ministry at Kidderminster in Worcestershire, when he also began a long and prolific career as a theological writer.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/15.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (16,'Thomas Cranmer','theologian','16th','Archbishop & Reformer','1489-1556','Thomas Cranmer was an English theologian who was a leader of the English Reformation and served as Archbishop of Canterbury during the reigns of Henry VIII, Edward VI and, for a short time, Mary I. He is honoured as a martyr in the Church of England.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/16.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (17,'Martin Bucer','theologian','16th','Reformer & Theologian','1491-1551','Martin Bucer was a German Protestant reformer based in Strasbourg who influenced Lutheran, Anglican doctrines and practices as well as Reformed Theology. Bucer was originally a member of the Dominican Order, but after meeting and being influenced by Martin Luther in 1518 he arranged for his monastic vows to be annulled. He then began to work for the Reformation, with the support of Franz von Sickingen.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/17.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (18,'William Carey','theologian','18th','Missionary & Translator','1761-1834','William Carey was an English Christian missionary, Particular Baptist minister, translator, social reformer and cultural anthropologist who founded the Serampore College and the Serampore University, the first degree-awarding university in India and cofounded the Serampore Mission Press.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/18.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (19,'A.W. Tozer','theologian','20th','Pastor & Author','1897-1963','Aiden Wilson Tozer was an American Christian pastor, author, magazine editor, and spiritual mentor. For his accomplishments, he received honorary doctorates from Wheaton and Houghton colleges.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/19.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (20,'Jan Hus','theologian','15th','Reformer & Martyr','1369-1415','Jan Hus, sometimes anglicized as John Goose or John Huss, and referred to in historical texts as Iohannes Hus or Johannes Huss, was a Czech theologian and philosopher who became a Church reformer and the inspiration of Hussitism, a key predecessor to Protestantism, and a seminal figure in the Bohemian Reformation. Hus is considered to be the first Church reformer, even though some designate the theorist John Wycliffe. His teachings had a strong influence, most immediately in the approval of a reformed Bohemian religious denomination and, over a century later, on Martin Luther.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/20.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (21,'Francis Schaeffer','theologian','20th','Philosopher & Apologist','1912-1984','Francis August Schaeffer was an American evangelical theologian, philosopher, and Presbyterian pastor. He co-founded the L''Abri community in Switzerland with his wife Edith Schaeffer, a prolific author in her own right. Opposed to theological modernism, Schaeffer promoted what he claimed was a more historic Protestant faith and a presuppositional approach to Christian apologetics, which he believed would answer the questions of the age.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/21.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (22,'Martyn Lloyd-Jones','theologian','20th','Preacher & Physician','1899-1981','David Martyn Lloyd-Jones was a Welsh Congregationalist minister and medical doctor who was influential in the Calvinist wing of the British evangelical movement in the 20th century. For almost 30 years, he was the minister of Westminster Chapel in London.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/22.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (23,'Watchman Nee','mystic','20th','Church Leader & Author','1903-1972','Watchman Nee, Ni Tuosheng, or Nee T''o-sheng, was a 20th century "Chinese evangelist, theologian, and founder of the Local Church movement." He was influenced in part by the Plymouth Brethren and the Wesleyan-holiness tradition.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/23.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (24,'François Fénelon','mystic','17th','Archbishop & Mystic','1651-1715','François de Salignac de la Mothe-Fénelon, P.S.S., more commonly known as François Fénelon, was a French Catholic archbishop, theologian, poet and writer. Today, he is remembered mostly as the author of The Adventures of Telemachus, first published in 1699. He was a member of the Sulpician Fathers.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/24.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (25,'Madame Guyon','mystic','17th','Mystic & Author','1648-1717','Jeanne-Marie Bouvier de La Motte Guyon was a French Christian accused of advocating Quietism, which was considered heretical by the Roman Catholic Church. Madame Guyon was imprisoned from 1695 to 1703 after publishing the book A Short and Very Easy Method of Prayer.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/25.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (26,'Thomas à Kempis','mystic','15th','Monk & Author','1380-1471','Thomas à Kempis was a German-Dutch Catholic canon regular of the Augustinians and the author of The Imitation of Christ, one of the best known Christian devotional books. His name means "Thomas of Kempen", Kempen, Germany, being his home town.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/26.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (27,'Brother Lawrence','mystic','17th','Monk & Mystic','1614-1691','Brother Lawrence of the Resurrection, OCD was a French Catholic religious brother who served at a Discalced Carmelite monastery, what is now Saint-Joseph-des-Carmes in Paris. He is best remembered for a posthumous book of his writing, the classic Christian text The Practice of the Presence of God.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/27.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (28,'Julian of Norwich','mystic','14th','Anchoress & Mystic','1342-1416','Julian of Norwich, also known as Juliana of Norwich, the Lady Julian, Dame Julian or Mother Julian, was a medieval English Catholic anchoress. Her writings, now known as Revelations of Divine Love, are the earliest surviving English-language works attributed to a woman. They are also the only surviving English-language works by an anchoress.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/28.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (29,'John of the Cross','mystic','16th','Mystic & Poet','1542-1591','St. John of the Cross was a Spanish Catholic priest, mystic, and Carmelite friar. He is a major figure of the Counter-Reformation in Spain, and he is one of the 38 Doctors of the Church.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/29.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (30,'Teresa of Ávila','mystic','16th','Mystic & Reformer','1515-1582','Teresa of Ávila, also called Saint Teresa of Jesus, was a Carmelite nun and prominent Spanish mystic and religious reformer.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/30.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (31,'Bernard of Clairvaux','mystic','12th','Abbot & Theologian','1090-1153','Bernard of Clairvaux, O.Cist., venerated as Saint Bernard, was an abbot, mystic, co-founder of the Knights Templar, and a major leader in the reform of the Benedictines through the nascent Cistercian Order.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/31.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (32,'Francis of Assisi','mystic','13th','Friar & Founder','1181-1226','Giovanni di Pietro di Bernardone, known as Francis of Assisi, was an Italian mystic, poet and Catholic friar who founded the religious order of the Franciscans. Inspired to lead a Christian life of poverty, he became a beggar and an itinerant preacher.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/32.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (33,'Hildegard of Bingen','mystic','12th','Abbess & Visionary','1098-1179','Hildegard of Bingen OSB, also known as the Sibyl of the Rhine, was a German Benedictine abbess and polymath active as a writer, composer, philosopher, mystic, visionary, and as a medical writer and practitioner of the Catholic Church during the High Middle Ages. She is one of the best-known composers of sacred monophony, as well as the most recorded in modern history. A number of scholars have considered her to be the founder of scientific natural history in Germany.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/33.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (34,'Jean-Pierre de Caussade','mystic','18th','Jesuit Priest & Mystic','1675-1751','Jean Pierre de Caussade was a French Jesuit priest and writer. He is especially known for the work ascribed to him known as Abandonment to Divine Providence, and also his work with the Nuns of the Visitation in Nancy, France.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/34.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (35,'Richard Rolle','mystic','14th','Hermit & Mystic','1300-1349','Richard Rolle was an English hermit, mystic, and religious writer. He is also known as Richard Rolle of Hampole or de Hampole, since at the end of his life he lived near a Cistercian nunnery in Hampole, now in South Yorkshire. In many ways, he can be considered the first English author due to the reported influence of his vernacular works starting soon after his death and continuing for centuries. Indeed, until the nineteenth century northern English medieval religious texts were regularly mis-attributed to him because of his ongoing authority.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/35.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (36,'Augustine of Hippo','church_father','4th','Bishop & Church Father','354-430','Augustine of Hippo was a Christian theologian and philosopher from Roman Africa and the Bishop of Hippo Regius. He is generally regarded as one of the most influential philosophers in the history of the Western world, and he is viewed as one of the most important Church Fathers of the Latin Church in the Patristic Period.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/36.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (37,'Athanasius','church_father','4th','Bishop & Theologian','296-373','Athanasius I of Alexandria, also called Athanasius the Great, Athanasius the Confessor, or, among Coptic Christians, Athanasius the Apostolic, was a Christian theologian and the 20th patriarch of Alexandria. His intermittent episcopacy spanned 45 years, of which over 17 encompassed five exiles, when he was replaced on the order of four different Roman emperors. Athanasius was a Church Father, the chief proponent of Trinitarianism against Arianism, and a noted Egyptian Christian leader of the fourth century.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/37.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (38,'John Chrysostom','church_father','4th','Archbishop & Preacher','347-407','John Chrysostom was a Church Father who served as Archbishop of Constantinople. He is known for his preaching and public speaking, his Divine Liturgy of Saint John Chrysostom, and his ascetic sensibilities.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/38.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (39,'Origen','church_father','3rd','Theologian & Scholar','184-253','Origen of Alexandria, also known as Origen Adamantius, was an early Christian scholar, ascetic, and theologian who was born and spent the first half of his career in Alexandria. He was a prolific writer who wrote roughly 2,000 treatises in multiple branches of theology, including textual criticism, biblical exegesis and hermeneutics, homiletics, and spirituality. He was one of the most influential and controversial figures in early Christian theology, apologetics, and asceticism. He has been described by John Anthony McGuckin as "the greatest genius the early church ever produced".','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/39.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (40,'Polycarp','church_father','2nd','Bishop & Martyr','69-155','Polycarp was a Christian bishop of Smyrna. According to the Martyrdom of Polycarp, he died a martyr, bound and burned at the stake, then stabbed when the fire failed to consume his body. Polycarp is regarded as a saint and Church Father in the Eastern Orthodox Church, the Catholic Church, Oriental Orthodox Churches, Lutheranism, and Anglicanism.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/40.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (41,'Ignatius of Antioch','church_father','1st','Bishop & Martyr','35-108','Ignatius of Antioch, also known as Ignatius Theophorus, was an early Christian writer and the Patriarch of Antioch. While en route to Rome, where he was to be killed, Ignatius wrote a series of letters. This correspondence forms a central part of a later collection of works by the Apostolic Fathers. He is considered one of the three most important of these, together with Clement of Rome and Polycarp. Although the authenticity of his letters has been questioned, they continue to serve as an example of early Christian theology, and address important topics including ecclesiology, the sacraments, and the role of bishops.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/41.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (42,'Irenaeus','church_father','2nd','Bishop & Theologian','130-202','Irenaeus was a Greek bishop noted for his role in guiding and expanding Christian communities in the southern regions of present-day France and, more widely, for the development of Christian theology by opposing Gnostic interpretations of Christian Scripture and defending orthodoxy. Originating from Smyrna, he had seen and heard the preaching of Polycarp, who in turn was said to have heard John the Evangelist.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/42.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (43,'Clement of Alexandria','church_father','2nd','Theologian & Scholar','150-215','Titus Flavius Clemens, also known as Clement of Alexandria, was a schematic Christian theologian and philosopher who taught at the Catechetical School of Alexandria. Among his pupils were Origen and Alexander of Jerusalem. A convert to Christianity, he was an educated man who was familiar with classical Greek philosophy and literature. As his three major works demonstrate, Clement was influenced by Hellenistic philosophy to a greater extent than any other Christian thinker of his time, and in particular, by Plato and the Stoics. His secret works, which exist only in fragments, suggest that he was familiar with pre-Christian Jewish esotericism and Gnosticism as well. In one of his works he argued that Greek philosophy had its origin among non-Greeks, claiming that both Plato and Pythagoras were taught by Egyptian scholars.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/43.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (44,'Cyprian of Carthage','church_father','3rd','Bishop & Martyr','200-258','Cyprian was a bishop of Carthage and an early Christian writer of Berber descent, many of whose Latin works are extant. He is recognized as a saint in the Western and Eastern churches.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/44.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (45,'Basil the Great','church_father','4th','Bishop & Theologian','330-379','Basil of Caesarea, also called Saint Basil the Great, was an early Christian prelate of the who served as Bishop of Caesarea Mazaca in Cappadocia from 370 until his death in 379. He was an influential theologian who supported the Nicene Creed and opposed heresies within the early Christian church such as Arianism and Apollinarianism.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/45.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (46,'Gregory of Nyssa','church_father','4th','Bishop & Theologian','335-395','Gregory of Nyssa, also known as Gregory Nyssen, was an early Christian theologian who served as the bishop of Nyssa from 372 to 376 and from 378 until his death in 394. He is venerated as a saint in Eastern Orthodoxy, the Catholic Church, Oriental Orthodox Churches, Anglicanism, and Lutheranism. Gregory, his elder brother Basil of Caesarea, and their friend Gregory of Nazianzus are collectively known as the Cappadocian Fathers.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/46.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (47,'Gregory of Nazianzus','church_father','4th','Archbishop & Poet','329-390','Gregory of Nazianzus, also known as  Saint Gregory the Theologian or Gregory Nazianzen, was an early Roman Christian theologian and prelate who served as Archbishop of Constantinople from 380 to 381. He is widely considered the most accomplished rhetorical stylist of the patristic age. As a classically trained orator and philosopher, he infused Hellenism into the early Church, establishing the paradigm of Byzantine theologians and church officials.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/47.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (48,'Ambrose of Milan','church_father','4th','Bishop & Theologian','340-397','Ambrose of Milan, canonized as Saint Ambrose, was a theologian and statesman who served as Bishop of Milan from 374 to 397.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/48.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (49,'Jerome','church_father','4th','Scholar & Bible Translator','347-420','Jerome, also known as Jerome of Stridon, was an early Christian priest, confessor, theologian, translator, and historian; he is commonly known as Saint Jerome.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/49.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (50,'Justin Martyr','church_father','2nd','Apologist & Martyr','100-165','Justin, known posthumously as Justin Martyr, also known as Justin the Philosopher, was an early Christian apologist and philosopher.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/50.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (51,'Martin Luther King Jr.','social_justice','20th','Pastor & Civil Rights Leader','1929-1968','Martin Luther King Jr. was an American civil rights activist and Baptist minister who was a prominent leader of the civil rights movement from 1955 until his assassination in 1968. He advanced civil rights for people of color in the United States through the use of nonviolent resistance and civil disobedience against Jim Crow laws and other forms of legalized discrimination, which most commonly affected African Americans.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/51.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (52,'William Wilberforce','social_justice','18th','Politician & Abolitionist','1759-1833','William Wilberforce was a British politician, philanthropist, and a leader of the movement to abolish the Atlantic slave trade. A native of Kingston upon Hull, Yorkshire, he began his political career in 1780, and became an independent Member of Parliament (MP) for Yorkshire (1784–1812). In 1785, he underwent a conversion experience and became an evangelical Anglican, which resulted in major changes to his lifestyle and a lifelong concern for reform.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/52.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (53,'Harriet Tubman','social_justice','19th','Abolitionist & Activist','1822-1913','Harriet Tubman was an American abolitionist and social activist. After escaping slavery, Tubman made some 13 missions to rescue approximately 70 enslaved people, including her family and friends, using the network of antislavery activists and safe houses known collectively as the Underground Railroad. During the American Civil War, she served as an armed scout and spy for the Union Army. In her later years, Tubman was an activist in the movement for women''s suffrage.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/53.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (54,'Sojourner Truth','social_justice','19th','Abolitionist & Activist','1797-1883','Sojourner Truth was an American abolitionist and activist for African-American civil rights, women''s rights, and alcohol temperance. Truth was born into slavery in Swartekill, New York, but escaped with her infant daughter to freedom in 1826. After going to court to recover her son in 1828, she became the first black woman to win such a case against a white man.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/54.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (55,'Desmond Tutu','social_justice','20th','Archbishop & Activist','1931-2021','Desmond Mpilo Tutu was a South African Anglican bishop and theologian, known for his work as an anti-apartheid and human rights activist. He was Bishop of Johannesburg from 1985 to 1986 and then Archbishop of Cape Town from 1986 to 1996, in both cases being the first Black African to hold the position. Theologically, he sought to fuse ideas from Black theology with African theology.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/55.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (56,'Frederick Douglass','social_justice','19th','Abolitionist & Statesman','1818-1895','Frederick Douglass was an American social reformer, abolitionist, orator, writer, and statesman. He was the most important leader of the movement for African-American civil rights in the 19th century.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/56.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (57,'Abraham Lincoln','social_justice','19th','President & Statesman','1809-1865','Abraham Lincoln was the 16th president of the United States, serving from 1861 until his assassination in 1865. He led the United States through the American Civil War, defeating the Confederate States and playing a major role in the abolition of slavery.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/57.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (58,'Corrie ten Boom','social_justice','20th','Holocaust Survivor & Evangelist','1892-1983','Cornelia Arnolda Johanna "Corrie" ten Boom was a Dutch watchmaker and later a Christian writer and public speaker, who worked with her father, Casper ten Boom, her sister Betsie ten Boom and other family members to help many Jewish people escape from the Nazis during the Holocaust in World War II by hiding them in her home. They were caught, and she was arrested and sent to the Ravensbrück concentration camp. Her most famous book, The Hiding Place, is a biography that recounts the story of her family''s efforts and how she found and shared hope in God while she was imprisoned at the concentration camp.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/58.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (59,'Eric Liddell','social_justice','20th','Athlete & Missionary','1902-1945','Eric Henry Liddell was a Scottish sprinter, rugby player and a Christian missionary. Born in Tianjin, China to Scottish missionary parents, he attended a boarding school near London, spending time when possible with his family in Edinburgh, and afterwards attended the University of Edinburgh.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/59.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (60,'Lord Shaftesbury','social_justice','19th','Politician & Reformer','1801-1885','Earl of Shaftesbury is a title in the Peerage of England. It was created in 1672 for Anthony Ashley-Cooper, 1st Baron Ashley, a prominent politician in the Cabal then dominating the policies of King Charles II. He had already succeeded his father as second Baronet of Rockbourne in 1631 and been created Baron Ashley, of Wimborne St Giles in the County of Dorset, in 1661, and he was made Baron Cooper, of Paulett in the County of Somerset, at the same time he was given the earldom.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/60.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (61,'Charles Finney','social_justice','19th','Revivalist & Abolitionist','1792-1875','Charles Grandison Finney was an American Presbyterian minister and leader in the Second Great Awakening in the United States. He has been called the "Father of Old Revivalism". Finney was a member of the New School Presbyterians and a part of the Holiness Movement.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/61.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (62,'John Newton','social_justice','18th','Clergyman & Abolitionist','1725-1807','John Newton was an English evangelical Anglican cleric and slavery abolitionist. He had previously been a captain of slave ships and an investor in the slave trade. Newton served as a sailor in the Royal Navy and was himself enslaved for a time in West Africa. Newton is noted for being author of the hymns "Amazing Grace" and "Glorious Things of Thee Are Spoken".','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/62.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (63,'Olaudah Equiano','social_justice','18th','Abolitionist & Author','1745-1797','Olaudah Equiano, known for most of his life as Gustavus Vassa, was a writer and abolitionist. According to his memoir, he was from the village of Essaka, presumed to be in present-day southern Nigeria. Enslaved as a child in West Africa, he was shipped to the Caribbean and sold to a Royal Navy officer. He was sold twice more before purchasing his freedom in 1766.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/63.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (64,'Howard Thurman','social_justice','20th','Theologian & Civil Rights Mentor','1899-1981','Howard Washington Thurman was an American author, philosopher, minister, theologian, Christian mystic, educator, and civil rights leader.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/64.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (65,'John Perkins','social_justice','20th','Pastor & Community Developer','1930-2023','John M. Perkins was an American Christian minister, civil rights activist and author. He was the founder and president of the John & Vera Mae Perkins Foundation with his wife, Vera Mae Perkins. Perkins was also co-founder of the Christian Community Development Association (CCDA).','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/65.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (66,'Isaac Newton','intellectual','17th','Physicist & Theologian','1643-1727','Sir Isaac Newton was an English polymath who was a mathematician, physicist, astronomer, alchemist, theologian, author and inventor. He was a key figure in the Scientific Revolution and the Enlightenment that followed. His book Philosophiæ Naturalis Principia Mathematica, first published in 1687, achieved the first great unification in physics and established classical mechanics. Newton also made seminal contributions to optics, and shares credit with the German mathematician Gottfried Wilhelm Leibniz for formulating infinitesimal calculus, although he developed calculus years before Leibniz. Newton contributed to and refined the scientific method, and his work is considered the most influential in bringing forth modern science.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/66.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (67,'Blaise Pascal','intellectual','17th','Mathematician & Philosopher','1623-1662','Blaise Pascal was a French mathematician, physicist, inventor, philosopher, and Catholic writer.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/67.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (68,'C.S. Lewis','intellectual','20th','Author & Apologist','1898-1963','Clive Staples Lewis was a British author, literary scholar and Anglican lay theologian. He held academic positions in English literature at both Magdalen College, Oxford (1925–1954), and Magdalene College, Cambridge (1954–1963). He is best known as the author of The Chronicles of Narnia, but he is also noted for his other works of fiction, such as The Screwtape Letters and The Space Trilogy, and for his non-fiction Christian apologetics, including Mere Christianity, Miracles and The Problem of Pain.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/68.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (69,'G.K. Chesterton','intellectual','20th','Author & Philosopher','1874-1936','Gilbert Keith Chesterton was an English Christian apologist writer. Chesterton''s wit, paradoxical style, and defence of tradition made him a dominant figure in early 20th-century literature.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/69.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (70,'Francis Bacon','intellectual','16th','Philosopher & Scientist','1561-1626','Francis Bacon, 1st Viscount St Alban was an English philosopher and statesman who served as Attorney General and Lord Chancellor of England under King James I. Bacon argued for the importance of natural philosophy, guided by the scientific method, and his works remained influential throughout the Scientific Revolution.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/70.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (71,'Galileo Galilei','intellectual','16th','Astronomer & Physicist','1564-1642','Galileo di Vincenzo Bonaiuti de'' Galilei, commonly referred to as Galileo Galilei, was an Italian astronomer, physicist, and engineer, sometimes described as a polymath. He was born in the city of Pisa, then part of the Duchy of Florence. Galileo has been called the father of observational astronomy, modern-era classical physics, the scientific method, and modern science.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/71.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (72,'Johannes Kepler','intellectual','16th','Astronomer & Mathematician','1571-1630','Johannes Kepler was a German polymath who was an astronomer, mathematician, astrologer, natural philosopher and music theorist. He is a key figure in the 17th-century Scientific Revolution, best known for his laws of planetary motion, and his books Astronomia nova, Harmonice Mundi, and Epitome Astronomiae Copernicanae. The variety and impact of his work made Kepler one of the founders and fathers of modern astronomy, the scientific method, natural science, and modern science. He has been described as the "father of science fiction" for his novel Somnium.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/72.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (73,'George Washington Carver','intellectual','19th','Scientist & Educator','1864-1943','George Washington Carver was an American agricultural scientist and inventor who promoted alternative crops to cotton and methods to prevent soil depletion. He was one of the most prominent black scientists of the early 20th century.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/73.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (74,'Gregor Mendel','intellectual','19th','Friar & Geneticist','1822-1884','Gregor Johann Mendel was an Austrian biologist, meteorologist, mathematician, Augustinian friar and abbot of St. Thomas'' Abbey in Brno (Brünn), Margraviate of Moravia. Mendel was born in a German-speaking family in the Silesian part of the Austrian Empire and gained posthumous recognition as the founder of the modern science of genetics. Though farmers had known for millennia that crossbreeding of animals and plants could favor certain desirable traits, Mendel''s pea plant experiments conducted between 1856 and 1863 established many of the rules of heredity, now referred to as the laws of Mendelian inheritance.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/74.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (75,'Francis Collins','intellectual','20th','Geneticist & Author','1950-present','Francis Sellers Collins is an American physician-scientist who discovered the genes associated with a number of diseases and led the Human Genome Project. He served as director of the National Institutes of Health (NIH) in Bethesda, Maryland, from 17 August 2009 to 19 December 2021, serving under three presidents. Collins announced his retirement publicly from the NIH on March 1, 2025, after 32 years of service.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/75.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (76,'Alexis de Tocqueville','intellectual','19th','Historian & Political Thinker','1805-1859','Alexis Charles Henri Clérel, comte de Tocqueville, was a French diplomat, political philosopher and historian. He is best known for his works Democracy in America and The Old Regime and the Revolution (1856). In both, he analyzed the living standards and social conditions of individuals as well as their relationship to the market and state in Western societies. Democracy in America was published after Tocqueville''s travels in the United States and is today considered an early work of sociology and political science.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/76.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (77,'Søren Kierkegaard','intellectual','19th','Philosopher & Theologian','1813-1855','Søren Aabye Kierkegaard was a Danish Lutheran theologian, philosopher, poet, social critic, and religious author who is widely considered to be the first existentialist philosopher. He wrote critical texts on organized religion, Christianity, morality, ethics, psychology, love, and the philosophy of religion, displaying a fondness for metaphor, irony, and parables. Much of his philosophical work deals with the issues of how one lives as a "single individual", highlighting the importance of authenticity, personal choice and commitment, and the duty to love. Kierkegaard prioritized concrete human reality over abstract thinking.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/77.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (78,'William James','intellectual','19th','Philosopher & Psychologist','1842-1910','William James was an American philosopher and psychologist. The first educator to offer a psychology course in the United States, he is considered to be one of the leading thinkers of the late 19th century, one of the most influential philosophers and is often dubbed the "father of American psychology".','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/78.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (79,'Dorothy Sayers','intellectual','20th','Author & Theologian','1893-1957','Dorothy Leigh Sayers was an English crime novelist, playwright, translator and critic.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/79.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (80,'John Lennox','intellectual','20th','Mathematician & Apologist','1943-present','John Carson Lennox is a Northern Irish mathematician, bioethicist, and lay theologian. He has written many books on religion, ethics, the relationship between science and God ; he has also participated in public debates with atheists, including Richard Dawkins and Christopher Hitchens.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/80.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (81,'Mother Teresa','missionary','20th','Nun & Missionary','1910-1997','Mary Teresa Bojaxhiu, better known as Mother Teresa or Saint Mother Teresa, was an Albanian-Indian Catholic nun, founder of the Missionaries of Charity and a Catholic saint.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/81.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (82,'Hudson Taylor','missionary','19th','Missionary to China','1832-1905','James Hudson Taylor is regarded as one of the most "important and influential missionaries of all time." He was a British Protestant Christian missionary to China and founder of the China Inland Mission. Taylor visited or lived in China over a period of 51 years. The CIM that he founded in 1865 became the largest of many missionary organizations in China. By 1910, it had more than 800 missionaries to the country, created 125 schools, and converted more than 20,000 Chinese to Christianity, as well as establishing more than 300 stations of work with more than 499 local helpers based in all 18 provinces.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/82.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (83,'Amy Carmichael','missionary','19th','Missionary & Author','1867-1951','Amy Beatrice Carmichael was an Irish Christian missionary in India who opened an orphanage and founded a mission in Dohnavur. She served in India for 55 years and wrote 35 books about her work as a missionary.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/83.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (84,'David Livingstone','missionary','19th','Missionary & Explorer','1813-1873','David Livingstone was a Scottish doctor, Congregationalist, pioneer Christian missionary with the London Missionary Society, and an explorer in Africa. Livingstone was married to Mary Moffat Livingstone, from the prominent 18th-century Moffat missionary family. Livingstone came to have a mythic status as a Protestant missionary martyr, working-class "rags-to-riches" inspirational story, scientific investigator and explorer, imperial reformer, anti-slavery crusader, and advocate of British commercial and colonial expansion. As a result, he became one of the most popular British heroes of the late 19th-century Victorian era.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/84.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (85,'Jim Elliot','missionary','20th','Missionary & Martyr','1927-1956','Philip James Elliot was an American Christian missionary and one of five people killed during Operation Auca, an attempt to evangelize the Huaorani people of Ecuador.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/85.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (86,'William Booth','missionary','19th','Founder of the Salvation Army','1829-1912','William Booth was an English Methodist preacher who, along with his wife, Catherine, founded the Salvation Army and became its first General (1878–1912). This Christian movement, founded in 1865, has a quasi-military structure and government and has spread from London to many parts of the world. It is one of the largest distributors of humanitarian aid.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/86.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (87,'Lottie Moon','missionary','19th','Missionary to China','1840-1912','Charlotte Digges "Lottie" Moon was an American Southern Baptist missionary to China with the Foreign Mission Board who spent nearly 40 years (1873–1912) living and working in China. As a teacher and evangelist she laid a foundation for traditionally solid support for missions among Southern Baptists, especially through its Woman''s Missionary Union.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/87.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (88,'Adoniram Judson','missionary','19th','Missionary to Burma','1788-1850','Adoniram Judson  was an American Particular Baptist missionary who worked in Burma for almost 40 years. At the age of 25, Judson was sent from North America to preach in Burma. His mission and work with Luther Rice led to the establishment of the Triennial Convention, the first national Baptist ecclesiastical organization, now called American Baptist Churches USA.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/88.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (89,'Mary Slessor','missionary','19th','Missionary to Africa','1848-1915','Mary Mitchell Slessor was a Scottish Presbyterian missionary to Nigeria. Once in Nigeria, Slessor learned Efik, one of many local languages, then began teaching. Because of her understanding of the native language and her bold personality Slessor gained the trust and acceptance of the locals and was able to spread Christianity while promoting women''s rights and protecting native children. She is most famous for her role in helping to stop the common practice of infanticide of twins in Okoyong, an area of Cross River State, Nigeria.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/89.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (90,'Count Zinzendorf','missionary','18th','Bishop & Missions Leader','1700-1760','Nikolaus Ludwig, Reichsgraf von Zinzendorf und Pottendorf was a German religious and social reformer, bishop of the Moravian Church, founder of the Herrnhuter Brüdergemeine, Christian mission pioneer and a major figure of 18th-century Protestantism.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/90.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (91,'George Müller','missionary','19th','Evangelist & Orphan Care Pioneer','1805-1898','George Müller was a Christian evangelist and the director of the Ashley Down orphanage in Bristol, England. He was one of the founders of the Plymouth Brethren movement. Later during the split, his group was called the Open Brethren.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/91.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (92,'Gladys Aylward','missionary','20th','Missionary to China','1902-1970','Gladys May Aylward was a British evangelical Christian missionary to China, whose story was told in the book The Small Woman: The Heroic Story of Gladys Aylward, by Alan Burgess, published in 1957. The book served as the basis for the film The Inn of the Sixth Happiness, starring Ingrid Bergman, in 1958. The film was produced by Twentieth Century Fox, and filmed entirely in North Wales and England.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/92.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (93,'C.T. Studd','missionary','19th','Missionary & Athlete','1860-1931','Charles Thomas Studd, often known as C. T. Studd, was a British missionary, a contributor to The Fundamentals, and a cricketer.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/93.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (94,'Jonathan Goforth','missionary','19th','Missionary to China','1859-1936','Jonathan Goforth was a Canadian Presbyterian missionary to China with the Canadian Presbyterian Mission, along with his wife, Florence Rosalind (Bell-Smith) Goforth. Jonathan Goforth became the foremost missionary revivalist in early 20th-century China and helped to establish revivalism as a major element in Protestant China missions.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/94.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (95,'Elisabeth Elliot','missionary','20th','Missionary & Author','1926-2015','Elisabeth Elliot was an American Christian missionary, author, and speaker. Her first husband, Jim Elliot, was killed in 1956 while attempting to make missionary contact with the Auca people of eastern Ecuador. She later spent two years as a missionary to the tribe members who killed her husband. After living in South America for many years, she returned to the United States, wrote over twenty books, and became widely known as an author and a speaker. Elliot toured the country well into her seventies, sharing her knowledge and talking about her experience.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/95.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (96,'Frank Laubach','missionary','20th','Missionary & Literacy Pioneer','1884-1970','Frank Charles Laubach, from Benton, Pennsylvania was a Congregational Christian missionary educated at Union Theological Seminary and Columbia University, and a mystic known as "The Apostle to the Illiterates." In 1915, while working among Muslims at a remote location in the Philippines, he developed the "Each One Teach One" literacy program. It has been used to teach about 60 million people to read in their own language. He was deeply concerned about poverty, injustice and illiteracy, and considered them barriers to peace in the world.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/96.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (97,'Samuel Zwemer','missionary','19th','Missionary to the Muslim World','1867-1952','Samuel Marinus Zwemer, nicknamed The Apostle to Islam, was an American missionary, traveler, and scholar. He was born at Vriesland, Michigan. In 1887 he received an A.B. from Hope College in Holland, Michigan, and in 1890, he received an M.A. from New Brunswick Theological Seminary in New Brunswick, New Jersey His other degrees include a D.D. from Hope College in 1904, a L.L.D. from Muskingum College in 1918, and a D.D. from Rutgers College in 1919.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/97.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (98,'Nate Saint','missionary','20th','Missionary Pilot & Martyr','1923-1956','Nathanael Saint was an evangelical Christian missionary pilot who, along with four others, was killed in Ecuador while attempting to evangelize the Huaorani people through efforts known as Operation Auca.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/98.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (99,'John G. Paton','missionary','19th','Missionary to the Pacific Islands','1824-1907','John Gibson Paton, born in Scotland, was a Protestant missionary to the New Hebrides Islands of the South Pacific. He brought to the natives of the New Hebrides education and Christianity. He developed small industries for them, such as hat making. He advocated strongly against a form of slavery, which was called "Blackbirding", that involved kidnapping the natives and forcing them to work in New Zealand and elsewhere.','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/99.webp',true);
INSERT INTO figures (id, name, category, century, role, lifespan, bio, themes, portrait_url, is_enabled) VALUES (100,'Andrew Murray','missionary','19th','Pastor & Author','1828-1917','Andrew Murray was a South African writer, teacher and Christian pastor. Murray considered missions to be "the chief end of the church".','','https://sfocythzurfdpkegjlsl.supabase.co/storage/v1/object/public/portraits/100.webp',true);
